import{_ as t,o as a,c as d,a2 as o}from"./chunks/framework.CHeM0PsO.js";const m=JSON.parse('{"title":"Herramientas MCP","description":"","frontmatter":{},"headers":[],"relativePath":"es/mcp-tools/overview.md","filePath":"es/mcp-tools/overview.md","lastUpdated":1784903584000}'),n={name:"es/mcp-tools/overview.md"};function r(s,e,c,i,l,p){return a(),d("div",null,[...e[0]||(e[0]=[o(`<h1 id="herramientas-mcp" tabindex="-1">Herramientas MCP <a class="header-anchor" href="#herramientas-mcp" aria-label="Permalink to &quot;Herramientas MCP&quot;">​</a></h1><h2 id="descripcion-general" tabindex="-1">Descripción General <a class="header-anchor" href="#descripcion-general" aria-label="Permalink to &quot;Descripción General&quot;">​</a></h2><p>swag2mcp proporciona <strong>19 herramientas MCP</strong> que dan a un agente LLM acceso completo a sus APIs a través del Protocolo de Contexto de Modelo. Estas herramientas cubren el flujo de trabajo completo: descubrir qué APIs están disponibles, navegar por la jerarquía de especificaciones, buscar e inspeccionar endpoints, ejecutar llamadas a la API y trabajar con respuestas grandes.</p><h3 id="que-resuelven-las-herramientas" tabindex="-1">Qué resuelven las herramientas <a class="header-anchor" href="#que-resuelven-las-herramientas" aria-label="Permalink to &quot;Qué resuelven las herramientas&quot;">​</a></h3><ul><li><strong>Descubrimiento</strong> — el LLM puede encontrar especificaciones, colecciones y etiquetas sin conocer los IDs de antemano</li><li><strong>Navegación</strong> — profundizar desde especificación → colección → etiqueta → endpoint en una jerarquía estructurada</li><li><strong>Búsqueda</strong> — búsqueda de texto completo en todos los endpoints cuando no tiene un ID</li><li><strong>Inspección</strong> — obtener el objeto de operación OpenAPI completo antes de hacer una llamada</li><li><strong>Ejecución</strong> — invocar llamadas reales a la API con autenticación automática</li><li><strong>Manejo de respuestas grandes</strong> — esquematizar, comprimir y segmentar respuestas demasiado grandes que no caben en línea</li></ul><h3 id="solo-lectura-vs-mutables" tabindex="-1">Solo lectura vs Mutables <a class="header-anchor" href="#solo-lectura-vs-mutables" aria-label="Permalink to &quot;Solo lectura vs Mutables&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tipo</th><th>Cantidad</th><th>Herramientas</th></tr></thead><tbody><tr><td><strong>Solo lectura</strong></td><td>17</td><td>Todas las herramientas de descubrimiento, endpoints, búsqueda, inspección, información y respuesta</td></tr><tr><td><strong>Mutables</strong></td><td>2</td><td><code>invoke</code> (realiza llamadas HTTP reales), <code>auth</code> (recupera tokens)</td></tr></tbody></table><p>Las herramientas de solo lectura están marcadas con <code>ReadOnlyHint=true</code> y <code>IdempotentHint=true</code> en el protocolo MCP, indicando al LLM que son seguras de llamar sin efectos secundarios.</p><h3 id="manejo-de-errores" tabindex="-1">Manejo de errores <a class="header-anchor" href="#manejo-de-errores" aria-label="Permalink to &quot;Manejo de errores&quot;">​</a></h3><p>Todas las herramientas devuelven errores como objetos <code>LLMError</code> estructurados con un código legible por máquina y un mensaje legible por humanos que explica qué salió mal y qué hacer a continuación:</p><table tabindex="0"><thead><tr><th>Código de error</th><th>Significado</th></tr></thead><tbody><tr><td><code>validation_failed</code></td><td>Entrada inválida (formato de ID incorrecto, campos requeridos faltantes)</td></tr><tr><td><code>not_found</code></td><td>Entidad no encontrada en el índice o espacio de trabajo</td></tr><tr><td><code>rate_limit</code></td><td>Segunda llamada <code>invoke</code> dentro de 10 segundos en el mismo endpoint</td></tr><tr><td><code>invoke_error</code></td><td>Fallo de llamada HTTP, fallo de descarga</td></tr><tr><td><code>auth_error</code></td><td>Fallo de recuperación de token de autenticación</td></tr><tr><td><code>config_error</code></td><td>Fallo de carga o guardado del archivo de configuración</td></tr><tr><td><code>parse_error</code></td><td>Fallo de análisis del archivo de especificación</td></tr></tbody></table><h2 id="categorias" tabindex="-1">Categorías <a class="header-anchor" href="#categorias" aria-label="Permalink to &quot;Categorías&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Categoría</th><th>Herramientas</th><th>Descripción</th></tr></thead><tbody><tr><td><strong>Descubrimiento</strong></td><td><code>spec_list</code>, <code>spec_by_id</code>, <code>collection_by_spec</code>, <code>collection_by_id</code>, <code>tag_by_spec</code>, <code>tag_by_collection</code>, <code>tag_by_id</code></td><td>Navegar por la jerarquía de especificaciones: encontrar especificaciones, colecciones y etiquetas</td></tr><tr><td><strong>Endpoints</strong></td><td><code>endpoint_by_spec</code>, <code>endpoint_by_collection</code>, <code>endpoint_by_tag</code>, <code>endpoint_by_id</code></td><td>Ver endpoints en diferentes niveles de la jerarquía</td></tr><tr><td><strong>Ejecución</strong></td><td><code>search</code>, <code>inspect</code>, <code>invoke</code></td><td>Buscar, inspeccionar el contrato completo y llamar APIs</td></tr><tr><td><strong>Utilidades</strong></td><td><code>auth</code>, <code>info</code>, <code>response_outline</code>, <code>response_compress</code>, <code>response_slice</code></td><td>Tokens de autenticación, información de ejecución y manejo de respuestas grandes</td></tr><tr><td><strong>Habilidades</strong></td><td><a href="/mcp-tools/skills">Guía de formato</a></td><td>Personalizar cómo se muestran las respuestas de las herramientas</td></tr></tbody></table><h2 id="lista-completa" tabindex="-1">Lista Completa <a class="header-anchor" href="#lista-completa" aria-label="Permalink to &quot;Lista Completa&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Herramienta</th><th>Descripción</th></tr></thead><tbody><tr><td><code>spec_list</code></td><td>Listar todas las especificaciones de API en el espacio de trabajo</td></tr><tr><td><code>spec_by_id</code></td><td>Obtener información detallada de la especificación con colecciones</td></tr><tr><td><code>collection_by_spec</code></td><td>Listar colecciones dentro de una especificación</td></tr><tr><td><code>collection_by_id</code></td><td>Obtener detalles de la colección con etiquetas</td></tr><tr><td><code>tag_by_spec</code></td><td>Listar todas las etiquetas en una especificación</td></tr><tr><td><code>tag_by_collection</code></td><td>Listar etiquetas dentro de una colección</td></tr><tr><td><code>tag_by_id</code></td><td>Obtener detalles de la etiqueta (ID, título, recuento de métodos)</td></tr><tr><td><code>endpoint_by_spec</code></td><td>Listar todos los endpoints en una especificación</td></tr><tr><td><code>endpoint_by_collection</code></td><td>Listar endpoints en una colección</td></tr><tr><td><code>endpoint_by_tag</code></td><td>Listar endpoints en una etiqueta</td></tr><tr><td><code>endpoint_by_id</code></td><td>Resumen rápido del endpoint (método, ruta, resumen)</td></tr><tr><td><code>search</code></td><td>Búsqueda de texto completo en todos los endpoints</td></tr><tr><td><code>inspect</code></td><td>Detalles completos de la operación OpenAPI (parámetros, esquemas)</td></tr><tr><td><code>invoke</code></td><td>Ejecutar una llamada real a la API</td></tr><tr><td><code>auth</code></td><td>Obtener token o encabezados de autenticación para una especificación</td></tr><tr><td><code>info</code></td><td>Información de ejecución (versión, especificaciones, configuración)</td></tr><tr><td><code>response_outline</code></td><td>Resumen estructural de un archivo de respuesta grande</td></tr><tr><td><code>response_compress</code></td><td>Comprimir una respuesta grande para que quepa en línea</td></tr><tr><td><code>response_slice</code></td><td>Extraer un fragmento de una respuesta grande</td></tr></tbody></table><h2 id="jerarquia-de-navegacion" tabindex="-1">Jerarquía de Navegación <a class="header-anchor" href="#jerarquia-de-navegacion" aria-label="Permalink to &quot;Jerarquía de Navegación&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>spec_list</span></span>
<span class="line"><span>  └── spec_by_id(id)</span></span>
<span class="line"><span>        └── collection_by_spec(specId)</span></span>
<span class="line"><span>              └── collection_by_id(id)</span></span>
<span class="line"><span>                    └── tag_by_collection(collectionId)</span></span>
<span class="line"><span>                          └── tag_by_id(id)</span></span>
<span class="line"><span>                                └── endpoint_by_tag(tagId)</span></span>
<span class="line"><span>                                      └── endpoint_by_id(id)</span></span>
<span class="line"><span>                                            └── inspect(endpointId)</span></span>
<span class="line"><span>                                                  └── invoke(endpointId)</span></span></code></pre></div><p>Cuando no tiene un ID, use <code>search</code> para encontrar endpoints por consulta. Cuando <code>invoke</code> devuelve un <code>fileRef</code> (respuesta demasiado grande), use <code>response_outline</code> → <code>response_compress</code> o <code>response_slice</code> para explorar los datos.</p>`,18)])])}const h=t(n,[["render",r]]);export{m as __pageData,h as default};
